// Convertit le brouillon validé (Markdown) en document ADF pour un commentaire Jira :
// titres, gras, italique, code, listes à puces et numérotées, tableaux.
// La mention « Statut : brouillon… » est retirée : le REX publié n'est plus un brouillon.

function enLigne(texte) {
  const noeuds = [];
  const motif = /(\*\*([^*]+)\*\*|`([^`]+)`|\*([^*\s][^*]*)\*|_([^_\s][^_]*)_)/g;
  let dernier = 0;
  let m;
  while ((m = motif.exec(texte)) !== null) {
    if (m.index > dernier) noeuds.push({ type: 'text', text: texte.slice(dernier, m.index) });
    if (m[2] !== undefined) noeuds.push({ type: 'text', text: m[2], marks: [{ type: 'strong' }] });
    else if (m[3] !== undefined) noeuds.push({ type: 'text', text: m[3], marks: [{ type: 'code' }] });
    else noeuds.push({ type: 'text', text: m[4] !== undefined ? m[4] : m[5], marks: [{ type: 'em' }] });
    dernier = motif.lastIndex;
  }
  if (dernier < texte.length) noeuds.push({ type: 'text', text: texte.slice(dernier) });
  return noeuds.filter((n) => n.text !== '');
}

const paragraphe = (texte) => ({ type: 'paragraph', content: enLigne(texte) });
const cellules = (ligne) => ligne.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
const estSeparateur = (ligne) => /^\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?$/.test(ligne.trim());

function versAdf(markdown) {
  const lignes = String(markdown || '')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .filter((l) => !/^\s*\**\s*Statut\s*:\s*brouillon/i.test(l));
  const blocs = [];
  let i = 0;
  while (i < lignes.length) {
    const ligne = lignes[i];
    const t = ligne.trim();
    if (t === '' || /^(-{3,}|\*{3,})$/.test(t)) { i += 1; continue; }

    const titre = t.match(/^(#{1,6})\s+(.*)$/);
    if (titre) {
      blocs.push({ type: 'heading', attrs: { level: Math.min(titre[1].length + 1, 6) }, content: enLigne(titre[2]) });
      i += 1;
      continue;
    }

    if (t.startsWith('|')) {
      const rangees = [];
      while (i < lignes.length && lignes[i].trim().startsWith('|')) {
        if (!estSeparateur(lignes[i])) rangees.push(cellules(lignes[i]));
        i += 1;
      }
      const largeur = Math.max(...rangees.map((r) => r.length));
      blocs.push({
        type: 'table',
        attrs: { isNumberColumnEnabled: false, layout: 'default' },
        content: rangees.map((r, n) => ({
          type: 'tableRow',
          content: Array.from({ length: largeur }, (_, k) => ({
            type: n === 0 ? 'tableHeader' : 'tableCell',
            attrs: {},
            content: [paragraphe(r[k] || '')],
          })),
        })),
      });
      continue;
    }

    const puce = /^[-*+]\s+/;
    const numero = /^\d+[.)]\s+/;
    if (puce.test(t) || numero.test(t)) {
      const ordonnee = numero.test(t);
      const motif = ordonnee ? numero : puce;
      const elements = [];
      while (i < lignes.length && motif.test(lignes[i].trim())) {
        elements.push({ type: 'listItem', content: [paragraphe(lignes[i].trim().replace(motif, ''))] });
        i += 1;
      }
      blocs.push({ type: ordonnee ? 'orderedList' : 'bulletList', content: elements });
      continue;
    }

    // Paragraphe : lignes consécutives réunies, séparées par un retour à la ligne.
    const contenu = [];
    while (i < lignes.length) {
      const l = lignes[i].trim();
      if (l === '' || /^#{1,6}\s/.test(l) || l.startsWith('|') || puce.test(l) || numero.test(l) || /^(-{3,}|\*{3,})$/.test(l)) break;
      if (contenu.length) contenu.push({ type: 'hardBreak' });
      contenu.push(...enLigne(l));
      i += 1;
    }
    blocs.push({ type: 'paragraph', content: contenu });
  }
  return blocs;
}

return $input.all().map((item, i) => {
  const r = item.json;
  const f = r.fields || r;
  const entete = { type: 'paragraph', content: [{ type: 'text', text: 'REX validé (relu par un humain avant publication)', marks: [{ type: 'em' }] }] };
  return {
    json: {
      recordId: r.id,
      issueKey: f.sys_id || f.Incident,
      adf: { type: 'doc', version: 1, content: [entete, ...versAdf(f.Brouillon)] },
    },
    pairedItem: { item: i },
  };
});
